import {SCHEMA,TYPES,LICENSES,escapeHTML as H,validateDraft,importWorkspace,splitRevenue,readiness,licenseBrief,hashFile} from './lex-core.js';
const $=s=>document.querySelector(s);const STORE='chlomlex.workspace.v1';let storageError='';let localData={drafts:[],events:[]};try{const raw=localStorage.getItem(STORE);if(raw){const d=JSON.parse(raw);if(!Array.isArray(d.drafts)||!Array.isArray(d.events))throw Error();d.drafts.forEach(validateDraft);localData=d;}}catch{storageError='Local storage could not be read. Export your work before leaving this page.';}
const state={...localData,user:null,cloud:[],cloudEvents:[],scope:'local',filter:'',archived:false,authMode:'signin'};let page='home',toastTimer,priorFocus;
const nav=[['workspace','◈','Overview'],['assets','▧','Assets'],['licenses','▤','License studio'],['exchange','⇄','Exchange'],['verify','⌕','Verify'],['splits','÷','Split planner'],['activity','◷','Activity'],['integrations','✣','Ecosystem'],['developers','⌘','Developers'],['status','◉','System status']];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4800);}
function persist(){try{localStorage.setItem(STORE,JSON.stringify({drafts:state.drafts,events:state.events.slice(0,500)}));storageError='';}catch{storageError='Browser storage is full or unavailable. Export your work before closing this page.';toast(storageError);}}
async function api(route,body,extra=''){const r=await fetch('/api/lex?route='+encodeURIComponent(route)+extra,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(22000)});let d;try{d=await r.json();}catch{throw Error('The service did not return a readable response. Local tools remain available.');}if(!r.ok||d.ok===false)throw Error(d.error||d.message||'The connected service could not complete this request.');return d;}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const date=x=>{const d=new Date(x);return Number.isNaN(d.getTime())?'Date unavailable':d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});};const badge=(text,kind='')=>`<span class="badge ${kind}">${H(text)}</span>`;const rows=()=>state.scope==='cloud'?state.cloud:state.drafts;const find=id=>rows().find(x=>x.id===id);const saveEvent=(type,row)=>{state.events.unshift({event_id:crypto.randomUUID(),draft_id:row.id,title:row.title,event_type:type,revision:row.revision,created_at:new Date().toISOString()});persist();};
function openModal(html){priorFocus=document.activeElement;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#modal-content input:not([type=hidden]),#modal-content button,#modal-content textarea')?.focus(),20);}
function closeModal(){$('#modal').close();priorFocus?.focus?.();}
function heading(title,subtitle,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="pageactions">${actions}</div></div>`;}
function action(label,act,id='',style=''){return `<button type="button" class="button ${style}" data-action="${act}" ${id?`data-id="${H(id)}"`:''}>${label}</button>`;}
function empty(title,text,button=''){return `<div class="panel empty"><div class="empty-mark" aria-hidden="true">✦</div><h2>${title}</h2><p>${text}</p>${button}</div>`;}
function scopeToolbar(){return `<div class="toolbar"><div class="tabs"><button data-action="scope-local" class="${state.scope==='local'?'selected':''}">This device</button><button data-action="scope-cloud" class="${state.scope==='cloud'?'selected':''}">Private cloud</button></div><span class="spacer"></span>${state.scope==='cloud'?action('Refresh','refresh','','small'):''}${action('Export workspace','export','','small')}${action('Import','import','','small')}</div>${storageError?`<div class="error">${H(storageError)}</div>`:''}`;}
function shell(content){const links=nav.map(([id,icon,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span>${label}</a>`).join('');return `<div class="workspace"><aside class="sidebar"><div class="sidebar-label">Your licensing workspace</div><nav class="sidenav" aria-label="Workspace">${links}</nav><div class="sidebottom">${badge(state.user?'Account connected':'Local-first workspace',state.user?'cloud':'local')}<p>Your originals stay yours. File checks run on your device.</p><a href="#privacy">How your data is handled ↗</a></div></aside><nav class="mobiletabs" aria-label="Workspace mobile">${links}</nav><main class="mainpane" id="main" tabindex="-1"><div class="breadcrumb">CHLOM LEX / ${H(nav.find(n=>n[0]===page)?.[2]||page)}</div>${content}</main></div>`;}
function home(){return `<main id="main"><section class="hero"><div><div class="eyebrow">Rights &amp; licensing, with intention</div><h1>Your work.<br>Your terms.<br><em>Your next chapter.</em></h1><p class="lead">Bring your creative assets, permissions, and licensing conversations into one considered workspace. Build value without losing the story behind it.</p><div class="heroactions"><a class="button dark" href="#assets">Start with your work <span>↗</span></a><a class="button" href="#verify">Verify a record <span>⌕</span></a></div><p class="quietline">Start free. No wallet required. Keep control of your originals.</p></div><div class="heroart" aria-label="Illustration of the asset-to-license workflow, not an issued credential"><div class="arttop"><span>A CLEARER PATH TO LICENSING</span><span>01 — 03</span></div><div class="passport"><div class="passport-head"><span>THE ASSET PASSPORT</span><span>LEX ✦</span></div><div class="passport-art"><div class="monogram">Aa</div><div class="orbit">✧</div></div><div class="passport-content"><small class="muted">FROM ORIGINAL WORK TO OPPORTUNITY</small><h3>Every work has a story.</h3><div class="passport-row"><span>01 &nbsp; Record</span><b>Identify the work &amp; source</b></div><div class="passport-row"><span>02 &nbsp; Define</span><b>Set the intended use</b></div><div class="passport-row"><span>03 &nbsp; Review</span><b>Connect the evidence</b></div></div></div><div class="artcaption"><span>WORKFLOW ILLUSTRATION · NOT A LICENSE</span><span>↗</span></div></div></section><div class="strip"><small>BUILT FOR THE WORK<br>YOU PUT INTO THE WORLD</small><span>Music &amp; audio</span><span>Books &amp; publishing</span><span>Visual media</span><span>Software &amp; tools</span><span>Culture &amp; education</span></div><section class="section"><div class="sectionhead"><div><div class="eyebrow">Less uncertainty. More intention.</div><h2>Give your work a<br>clear path forward.</h2></div><p>Not another folder of disconnected files. A practical starting point for the who, what, and how of licensing.</p></div><div class="three"><article class="feature"><span class="number">01 / YOUR ASSETS</span><h3>Start with the source.</h3><p>Name the work, identify the rights holder, and attach a file fingerprint without uploading your original.</p><a href="#assets">Open asset workspace <span>↗</span></a></article><article class="feature"><span class="number">02 / YOUR TERMS</span><h3>Define the opportunity.</h3><p>Build a licensing brief with clear uses, exclusions, territory, term, attribution, and proposed compensation.</p><a href="#licenses">Enter license studio <span>↗</span></a></article><article class="feature"><span class="number">03 / YOUR EVIDENCE</span><h3>Make the record count.</h3><p>Compare file digests, look up public CHLOM identities, and send private proposals into governed review.</p><a href="#verify">Explore verification tools <span>↗</span></a></article></div></section><section class="darkpanel"><div><div class="eyebrow">Built by CrownThrive</div><h2>The work is cultural.<br>The terms should<br>be clear.</h2><p>CHLOM LEX is the licensing workspace. CHLOM is the governing framework. The CrownThrive ecosystem connects the work to its next opportunity.</p><a href="#integrations" class="button lime">See the ecosystem <span>↗</span></a></div><div><div class="principle"><span>01</span><div>Rights before reach.<p>Document permission before expanding distribution.</p></div></div><div class="principle"><span>02</span><div>Context is part of the work.<p>Keep attribution, community considerations, and cultural intent in the conversation.</p></div></div><div class="principle"><span>03</span><div>Evidence, not assumptions.<p>A digest is not legal title. A draft is not an executed agreement. A review request is not an approval.</p></div></div></div></section><section class="cta"><div class="eyebrow">Your next move starts here</div><h2>Build the record.<br>Keep the possibility.</h2><p>Start with one asset. Bring the source, define the use, and make the next conversation a better one.</p><a href="#workspace" class="button dark">Open your workspace <span>↗</span></a></section></main>`;}
function overview(){const all=rows().filter(x=>x.state!=='ARCHIVED'),assets=all.filter(x=>x.kind==='asset'),licenses=all.filter(x=>x.kind==='license');return heading('A home for your next chapter.','Bring the work, its context, and its proposed terms together. Your first record is a starting point, not an ownership certificate.',action('+ Add asset','new-asset','','dark'))+scopeToolbar()+`<div class="workspace-stats"><div class="stat"><small>ASSET RECORDS</small><span class="value">${assets.length}</span>${badge(state.scope==='cloud'?'Cloud metadata':'This device',state.scope==='cloud'?'cloud':'local')}</div><div class="stat"><small>LICENSE BRIEFS</small><span class="value">${licenses.length}</span><small>Proposals, not grants</small></div><div class="stat"><small>REVIEW REQUESTS</small><span class="value">${all.filter(x=>x.state==='REVIEW_REQUESTED').length}</span><small>Awaiting governed review</small></div></div><div class="twocol"><div class="panel tinted"><div class="eyebrow">A useful place to begin</div><h2>Give one work a clear record.</h2><p>Start with the title, rights holder, source reference, and intended use. Add a SHA-256 digest to identify the exact file version.</p>${action('Create an asset record ↗','new-asset','','dark')}</div><div class="panel"><h2>Your working sequence</h2><div class="flow"><div class="flowstep"><span>01</span><div><b>Record the asset</b><small>Identify the original and its source.</small></div></div><div class="flowstep"><span>02</span><div><b>Draft the intended use</b><small>Choose a license class and define the boundaries.</small></div></div><div class="flowstep"><span>03</span><div><b>Submit a private review request</b><small>Sign in, save to cloud, and submit explicitly.</small></div></div></div></div></div><div class="rowend"><h2>Recent work</h2><a class="linkbutton" href="#assets">View assets ↗</a></div>${all.length?`<div class="records">${all.slice(0,4).map(recordCard).join('')}</div>`:empty('Your work belongs here.','No placeholder records. Add your first asset to begin.',action('Add your first asset','new-asset','','dark'))}`;}
function recordCard(r){const p=r.payload;return `<article class="record"><div class="record-top">${badge(r.kind==='asset'?(p.type||'Asset'):(p.licenseClass||'License brief'))}${badge(r.state==='REVIEW_REQUESTED'?'Review requested':r.state==='ARCHIVED'?'Archived':'Draft',r.state==='REVIEW_REQUESTED'?'pending':'local')}</div><h3>${H(r.title)}</h3><p>${H(r.kind==='asset'?(p.owner?'Rights holder (self-declared): '+p.owner:'Rights holder not recorded'):(p.licensee?'Proposed licensee: '+p.licensee:'Licensee not recorded'))}</p><div class="meta">${state.scope==='cloud'?'Private cloud':'This device'} · Revision ${H(r.revision||1)} · ${H(date(r.updated_at))}</div><div class="record-actions">${action('Open','open',r.id,'small')}${action('Edit','edit',r.id,'small')}${r.kind==='asset'?action('Draft a license','license-from',r.id,'small'):action('Export brief','brief',r.id,'small')}${state.scope==='local'?action('Save to cloud','cloud-save',r.id,'small'):action('Request review','review',r.id,'small')}</div></article>`;}
function recordsPage(kind){return heading(kind==='asset'?'Your assets. In context.':'License studio.',kind==='asset'?'Record the source, rights holder, and file version. Original files are hashed on your device and are never uploaded by this workspace.':'Build a structured proposal. No rights are granted until the appropriate agreement and approvals are recorded.',action(kind==='asset'?'+ Add asset':'+ Create brief',kind==='asset'?'new-asset':'new-license','','dark'))+scopeToolbar()+`<div class="toolbar"><label class="sr-only" for="search">Search records</label><input id="search" placeholder="Search titles, owners, or types…" value="${H(state.filter)}"><label class="checkfield"><input type="checkbox" id="show-archived" ${state.archived?'checked':''}> Include archived</label></div><div id="record-list">${recordList(kind)}</div>`;}
function recordList(kind){const list=rows().filter(x=>x.kind===kind&&(state.archived||x.state!=='ARCHIVED')&&`${x.title} ${x.payload.owner||''} ${x.payload.type||''}`.toLowerCase().includes(state.filter.toLowerCase()));return list.length?`<div class="records">${list.map(recordCard).join('')}</div>`:empty(state.filter?'No matching records.':kind==='asset'?'Every asset starts with a source.':'Set the terms before the next step.',state.filter?'Try another title, owner, or type.':kind==='asset'?'Add music, a manuscript, artwork, software, or another work you are preparing to license.':'Choose a work and describe the use you are proposing.',action(kind==='asset'?'Add an asset':'Create a license brief',kind==='asset'?'new-asset':'new-license','','dark'));}
function field(name,label,value='',type='text',required=false,full=false,extra=''){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${H(value)}" ${required?'required':''} ${extra}></label>`;}
function area(name,label,value='',full=true){return `<label class="field ${full?'full':''}">${label}<textarea name="${name}" maxlength="8000">${H(value)}</textarea></label>`;}
function selectField(name,label,options,value){return `<label class="field">${label}<select name="${name}">${options.map(x=>`<option value="${H(x)}" ${x===value?'selected':''}>${H(x)}</option>`).join('')}</select></label>`;}
function editDraft(kind,id=null,source=null){const r=id?find(id):null,p=r?.payload||{},asset=source?.payload||{};const title=r?.title||'';const assetOptions=rows().filter(x=>x.kind==='asset'&&x.state!=='ARCHIVED');let fields=field('title',kind==='asset'?'Work title':'Brief / project title',title,'text',true,false,'maxlength="160"');if(kind==='asset')fields+=selectField('type','Asset category',TYPES,p.type||TYPES[0]);else fields+=`<label class="field">Related asset<select name="assetId" id="asset-select"><option value="">Enter details manually</option>${assetOptions.map(a=>`<option value="${H(a.id)}" ${a.id===(p.assetId||source?.id)?'selected':''}>${H(a.title)}</option>`).join('')}</select></label>`;
fields+=field('owner','Rights holder (self-declared)',p.owner||asset.owner||'','text',true,false,'maxlength="250"')+field('source','Source / original reference',p.source||asset.source||'','text',false,false,'maxlength="1000"');
if(kind==='license')fields+=field('licensee','Proposed licensee',p.licensee||'','text',false,false,'maxlength="250"')+selectField('licenseClass','License class',LICENSES,p.licenseClass||LICENSES[0])+field('territory','Territory',p.territory||'','text',false,false,'placeholder="e.g. United States" maxlength="250"')+field('term','Term / duration',p.term||'','text',false,false,'placeholder="e.g. 12 months from execution" maxlength="250"')+field('seats','Seats / copies / audience',p.seats||'','text',false,false,'maxlength="250"')+selectField('exclusivity','Exclusivity (proposed)',['Nonexclusive','Exclusive — requires separate negotiation'],p.exclusivity||'Nonexclusive')+field('fee','Proposed fee',p.fee||'','number',false,false,'min="0" max="1000000000" step="0.01" placeholder="To be agreed"')+selectField('currency','Currency',['USD','EUR','GBP','CAD'],p.currency||'USD')+field('attribution','Attribution requirements',p.attribution||'','text',false,true,'maxlength="1000"');
fields+=area('use',kind==='asset'?'Intended uses / opportunities':'Permitted use being proposed',p.use||asset.use||'')+area('exclusions','Excluded uses / restrictions',p.exclusions||asset.exclusions||'')+area('context','Cultural context / consent considerations',p.context||asset.context||'');if(kind==='license')fields+=area('aiUse','AI training, voice, or likeness permissions',p.aiUse||'Not granted by this brief. Separate express permission required.');
fields+=`<div class="filebox full"><label class="field">Attach a file fingerprint, not the file<input type="file" id="draft-file"><small>Optional · up to 100 MB · SHA-256 runs entirely on your device.</small></label>${field('digest','SHA-256 digest',p.digest||asset.digest||'','text',false,false,'pattern="[0-9a-f]{64}" maxlength="64" placeholder="Select a file above, or paste its 64-character digest"')}<small id="file-note" class="muted">No original file will be uploaded or stored.</small></div>`;
openModal(`<h2 id="modal-title">${r?'Edit':kind==='asset'?'Record an':'Create a'} ${kind==='asset'?'asset':'license brief'}</h2><p class="modal-subtitle">${state.scope==='cloud'?'Saving to your private cloud account.':'Saving on this device only. Sign-in is not required.'} Ownership and permissions remain self-declared until reviewed.</p><form id="draft-form" data-kind="${kind}" data-id="${H(id||'')}"><div class="fieldgrid">${fields}</div><div id="form-error" role="alert"></div><div class="formfooter"><small>A draft is a working record, not a verified claim or an executed license.</small><div>${action('Cancel','close')}<button class="button dark" type="submit">Save ${state.scope==='cloud'?'to cloud':'draft'} ↗</button></div></div></form>`);}
function viewDraft(id){const r=find(id);if(!r)return;const ready=readiness({...r.payload,title:r.title});openModal(`<h2 id="modal-title">${H(r.title)}</h2><div class="rowend">${badge(r.kind==='asset'?'Asset record':'License proposal')}${badge(r.state==='REVIEW_REQUESTED'?'Review requested':'Draft','pending')}</div><p class="modal-subtitle">${state.scope==='cloud'?'Private cloud':'This device'} · Revision ${H(r.revision||1)} · ${H(date(r.updated_at))}</p><div class="notice">Documentation completeness: ${ready.complete} of ${ready.total} fields. This is not a rights or legal assessment.</div><ul class="checks">${ready.checks.map(([s,v])=>`<li><span class="checkmark">${v?'✓':'○'}</span>${H(s)}</li>`).join('')}</ul><div class="result-grid">${Object.entries(r.payload).filter(([,v])=>v!==''&&v!=null&&typeof v!=='object').map(([k,v])=>`<div><small>${H(k.replace(/([A-Z])/g,' $1'))}</small>${H(v)}</div>`).join('')}</div>${r.review_case_id?`<div class="notice">Canonical CHLOM review case: <span class="hash">${H(r.review_case_id)}</span></div>`:''}<div class="formfooter"><small>Original files are not included in this record.</small><div>${action('Export JSON','record-export',id,'small')}${action('Edit','edit',id,'small dark')}${action('Archive','archive',id,'small')}</div></div>`);}
function verifyPage(){return heading('Check the record. Know the difference.','Compare file bytes or resolve a public CHLOM identity. Neither tool decides ownership, legal rights, or permission to use a work.')+`<div class="twocol"><section class="panel"><div class="eyebrow">On-device verification</div><h2>File fingerprint</h2><p>Calculate SHA-256 and optionally compare it with an expected digest. No file is uploaded.</p><form id="verify-file-form"><label class="field">Choose a file<input type="file" name="file" required><small>Up to 100 MB.</small></label><div class="divider"></div>${field('expected','Expected SHA-256 (optional)','','text',false,false,'pattern="[0-9a-fA-F]{64}" maxlength="64" placeholder="64 hexadecimal characters"')}<div class="formfooter"><small>Byte equality is not proof of authorship.</small><button class="button dark">Check file ↗</button></div></form><div id="file-result" aria-live="polite"></div></section><section class="panel"><div class="eyebrow">Connected public resolver</div><h2>Public identity lookup</h2><p>Look up an intentionally published CHLOM identity and its public lineage. Private evidence stays private.</p><form id="resolve-form">${field('identity','Public CHLOM identifier','','text',true,true,'pattern="ctid_[0-9a-f]{32}" maxlength="37" placeholder="ctid_ followed by 32 hexadecimal characters"')}<div class="formfooter"><small>Public records only. No private identifiers.</small><button class="button dark">Look up record ↗</button></div></form><div id="identity-result" aria-live="polite"></div></section></div><div class="panel tinted"><h2>What a result does — and does not — mean</h2><div class="three"><div><h3>A matching digest</h3><p>The selected file matches the supplied SHA-256 digest. The digest alone does not establish who created it.</p></div><div><h3>A public identity</h3><p>The resolver found a published identity record. Read its state and lineage; do not treat it as a license.</p></div><div><h3>A licensing decision</h3><p>Authority, permissions, evidence, and signed terms still require the appropriate separate review.</p></div></div></div>`;}
function exchangePage(){return heading('The right work. The right terms.','Explore only explicitly published, eligible offers from the canonical CHLOM registry. Private drafts and internal offers never populate this exchange.',action('Draft a licensing request','new-license','','dark'))+`<div id="catalog" class="panel loading" aria-live="polite">Reading the public offer registry…</div><div class="sectionhead"><div><div class="eyebrow">Start a conversation</div><h2>What are you looking to license?</h2></div></div><div class="categorygrid">${TYPES.map((t,i)=>`<button class="category" data-action="category" data-category="${H(t)}"><span aria-hidden="true">${['♫','▤','◩','⌘','✧','◈'][i]}</span><strong>${H(t)}</strong><small>Create a request brief ↗</small></button>`).join('')}</div><div class="notice">The exchange does not activate checkout, transfer ownership, or execute payments. Commercial terms and fulfillment must be confirmed per offer.</div>`;}
async function hydrateCatalog(){try{const d=await api('catalog');if(page!=='exchange')return;$('#catalog').className='panel';$('#catalog').innerHTML=d.offers?.length?`<div class="records">${d.offers.map(o=>`<article class="record">${badge('Published offer','cloud')}<h3>${H(o.label||o.offer_id)}</h3><p>${H(o.license_class)}</p><div class="hash">${H(o.offer_id)} · ${H(o.offer_version)}</div><div class="notice">${o.price==null?'Terms on request':H(o.price)+' '+H(o.currency||'')} · No checkout activated here.</div>${action('Prepare an inquiry','new-license','','small dark')}</article>`).join('')}</div>`:`<div class="empty"><div class="empty-mark">⇄</div><h2>No public offers are listed yet.</h2><p>The registry returned no current eligible public offers. You can still prepare a licensing request or organize work for review.</p>${action('Prepare a request','new-license','','dark')}<p class="supportline">Registry checked ${H(date(d.checked_at))}.</p></div>`;}catch(e){if($('#catalog'))$('#catalog').innerHTML=`<div class="error">${H(e.message)}</div><p>The catalog could not be verified. No cached or sample offers are being shown.</p>${action('Retry catalog','catalog-retry','','small')}`;}}
function splitsPage(){return heading('Plan the split. Keep the math clear.','Model a proposed allocation with exact cent reconciliation. This planner does not send money, calculate taxes, or create royalty obligations.')+`<div class="twocol"><section class="panel"><h2>Build a scenario</h2><form id="split-form"><div class="fieldgrid">${field('gross','Gross amount','1000','number',true,false,'min="0" max="10000000000" step="0.01"')}${field('fees','Total fees / deductions','0','number',true,false,'min="0" step="0.01"')}${selectField('currency','Currency',['USD','EUR','GBP','CAD'],'USD')}</div><div class="divider"></div><p>Recipients and proposed share (%)</p><div id="split-recipients">${splitRow('Rights holder',70)}${splitRow('Collaborator',30)}</div>${action('+ Add recipient','add-recipient','','small')}<div id="split-error" role="alert"></div><div class="formfooter"><small>Shares must total 100%. Remainder cents use the largest-remainder method.</small><button class="button dark">Calculate split ↗</button></div></form></section><section class="panel" id="split-result"><div class="empty"><div class="empty-mark">÷</div><h2>A scenario, not a settlement.</h2><p>Calculate to see the net amount and a per-recipient allocation. No provider fees are assumed.</p></div></section></div>`;}
function splitRow(name='',percentage=''){return `<div class="splitrow"><input name="recipient" aria-label="Recipient name" value="${H(name)}" placeholder="Recipient name" maxlength="160" required><input name="share" type="number" aria-label="Percentage share" value="${H(percentage)}" min="0" max="100" step="0.01" required><button type="button" data-action="remove-recipient" aria-label="Remove recipient">×</button></div>`;}
function activityPage(){const list=state.scope==='cloud'?state.cloudEvents:state.events;return heading('A record of your work.','Actual workspace changes and review submissions. Local activity is browser-held; cloud draft history is retained with your account.')+scopeToolbar()+(list.length?`<section class="panel"><ol class="timeline">${list.slice(0,100).map(e=>`<li><span>◷</span><div><b>${H(String(e.event_type).replaceAll('_',' '))}</b> · ${H(e.title||e.draft_id)}<time>${H(date(e.created_at))} · Revision ${H(e.revision||1)}</time>${e.payload_sha256?`<div class="hash">Snapshot SHA-256: ${H(e.payload_sha256)}</div>`:''}${e.review_case_id?`<div class="hash">CHLOM review: ${H(e.review_case_id)}</div>`:''}</div></li>`).join('')}</ol></section>`:empty('Your record starts with your first action.','Add or edit an asset, save a license brief, or submit a cloud draft for review. No sample activity is displayed.'));}
function ecosystemPage(){const cards=[['CHLOM','Governing framework','Rights, rules, roles, revenue, records, and remedies. LEX review requests connect to the existing CHLOM review registry.','Native review connection'],['Cultural Imprint Engine','Context & cultural intent','Carry cultural context, attribution, consent considerations, and community impact into asset and license briefs.','Context fields available'],['CrownThrive OS','Operations & oversight','The existing CrownThrive command center remains the wider operational home. LEX does not replace its authority.','Existing command center'],['Virality Music · Melanated TV · Melanated Voices','Music, media & storytelling','Prepare music, publishing, screen, and storytelling rights conversations with work-specific evidence and terms.','Ecosystem pathway'],['Go Flipbooks · CrownThriveU','Publishing & education','Define reader, classroom, church, household, and professional uses before packaging or distribution.','Ecosystem pathway'],['AdLuxe · CrownFluence · CrownLytics','Distribution & measurement','Align advertising and creator use with approved rights. Distribution and analytics remain separate systems.','Ecosystem pathway']];return heading('One ecosystem. Distinct responsibilities.','LEX is a focused licensing workspace inside CrownThrive—not a claim that every platform is automatically connected or approved.')+`<div class="records">${cards.map(c=>`<article class="panel"><div class="eyebrow">${H(c[1])}</div><h2>${H(c[0])}</h2><p>${H(c[2])}</p>${badge(c[3],c[3]==='Native review connection'?'cloud':'local')}</article>`).join('')}</div><div class="panel dark"><h2>Context → record → review → opportunity.</h2><p>CrownThrive’s Thrive Flywheel connects cultural creation, governed permissions, publishing, distribution, and reinvestment. A platform’s role is not the same as a verified technical integration.</p><div class="heroactions"><a class="button lime" href="https://crownthrive.com" target="_blank" rel="noopener">Explore CrownThrive ↗</a><a class="button" href="https://crown-thrive-os.vercel.app" target="_blank" rel="noopener">Open CrownThrive OS ↗</a></div></div>`;}
function developersPage(){return heading('Built on the protocol. Not beside it.','The LEX web adapter retains the signed-in user’s identity. Native CHLOM operator roles, scopes, idempotency, and review authority still apply.')+`<div class="twocol"><section class="panel"><h2>Public and private interfaces</h2><div class="tablewrap"><table><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /api/lex?route=health</code></td><td>Adapter identity</td></tr><tr><td><code>GET …route=catalog</code></td><td>Eligible public offers</td></tr><tr><td><code>GET …route=resolve&amp;id=ctid_…</code></td><td>Public identity</td></tr><tr><td><code>GET …route=drafts</code></td><td>Own private drafts</td></tr><tr><td><code>POST …route=save</code></td><td>Versioned private proposal</td></tr><tr><td><code>POST …route=review</code></td><td>Canonical review request</td></tr><tr><td><code>GET/POST …route=operator</code></td><td>Native authorized dispatcher</td></tr></tbody></table></div><p class="supportline">Writes require an authenticated session and same-origin JSON requests. This browser adapter is not a public administrative API.</p></section><section class="panel"><h2>CHLOM operator access</h2><p>Signing in to a workspace does not grant operator authority. Check the permissions actually associated with your account.</p>${action('Check my operator access','operator-check','','dark')}<div id="operator-result" aria-live="polite"></div><div class="divider"></div><h3>Preserved protocol interfaces</h3><p>Existing health, REST, and MCP routes remain in place. Their runtime readiness is reported separately.</p><a class="button small" href="/protocol">Open protocol diagnostics ↗</a></section></div><section class="panel"><h2>Export contract</h2><p>A portable JSON workspace export contains user-authored drafts. Imports create fresh local copies; imported states, IDs, and authority assertions are not trusted.</p><pre>${H(JSON.stringify({schema:SCHEMA,exported_at:'ISO-8601 timestamp',drafts:[{kind:'asset',title:'Your work title',payload:{owner:'Self-declared rights holder',type:'Music & audio',source:'Original source reference',digest:'SHA-256 when provided'}}]},null,2))}</pre></section>`;}
function pricingPage(){return heading('Start with the work. Not a subscription.','Use the workspace to prepare real records and licensing conversations. There is no automatic payment or paid entitlement created by this site.')+`<div class="three"><section class="panel pricecard"><div class="eyebrow">Workspace</div><h2>A clear place to start.</h2><div class="price">Free</div><p>Asset records, license briefs, local file hashing, import/export, and split planning. Account-based private draft storage and review-request intake are included in this release.</p><div class="notice">Up to 1,000 private cloud draft records per account. Originals are not uploaded.</div><a class="button dark" href="#workspace">Open workspace ↗</a></section><section class="panel pricecard"><div class="eyebrow">Asset licensing</div><h2>Terms that fit the work.</h2><div class="price">Per asset</div><p>License scope, fees, permitted use, and delivery are agreed for the specific work. A draft brief is not an executed license.</p><div class="notice">No public checkout is active in this release. Published eligibility and fulfillment must be verified separately.</div><a class="button" href="#exchange">Explore exchange ↗</a></section><section class="panel pricecard"><div class="eyebrow">Teams & institutions</div><h2>A considered conversation.</h2><div class="price">Custom</div><p>Discuss a rights catalog, education collection, media slate, or organizational workflow with CrownThrive. Team seats, service scope, and pricing require a separate agreement.</p><a class="button" href="mailto:contact@crownthrive.com?subject=CHLOM%20LEX%20institutional%20inquiry">Discuss your project ↗</a></section></div>`;}
function statusPage(){return heading('What is working. What is separate.','Read current responses rather than treating a deployed page as proof that every provider or protocol capability is ready.',action('Refresh status','status-retry','','small'))+`<div id="service-status" class="panel loading">Checking adapter and protocol responses…</div><div class="notice">Public website availability, private workspace access, operator authorization, payments, and chain execution are different states. A healthy page does not certify them all.</div>`;}
async function hydrateStatus(){const results=await Promise.allSettled([api('health'),fetch('/api/health',{cache:'no-store',signal:AbortSignal.timeout(18000)}).then(async r=>{if(!r.ok)throw Error('Protocol returned HTTP '+r.status);return r.json();}),api('catalog')]);if(page!=='status')return;$('#service-status').className='panel';$('#service-status').innerHTML=`<div class="tablewrap"><table><thead><tr><th>Component</th><th>Observed result</th></tr></thead><tbody>${results.map((r,i)=>`<tr><td>${['LEX web adapter','CHLOM Chain Evidence Fabric','Public catalog'][i]}</td><td>${r.status==='fulfilled'?H(i===0?'Responding · v'+r.value.version:i===1?((r.value.status||r.value.runtime?.status||'Responding')+' · '+(r.value.readinessStatus||r.value.readiness?.status||'See readiness details')):r.value.offers.length+' eligible public offers'):H(r.reason.message)}</td></tr>`).join('')}<tr><td>Private cloud workspace</td><td>${state.user?'Account session connected':'Sign-in required'}</td></tr><tr><td>Payments / chain settlement</td><td>Not executed by LEX</td></tr></tbody></table></div><p class="supportline">Checked ${H(date(new Date()))}. Provider configuration can change independently of the interface.</p>${results[1].status==='fulfilled'?`<details><summary>Protocol readiness details</summary><pre>${H(JSON.stringify(results[1].value.readiness||{},null,2))}</pre></details>`:''}`;}
function policyPage(terms){return heading(terms?'Use & boundaries.':'Your records. Clear handling.',terms?'Operational terms for this CHLOM LEX release.':'How this release handles account details, file fingerprints, and draft metadata.')+`<article class="panel prose">${terms?`<h2>What the workspace provides</h2><p>CHLOM LEX provides tools to organize asset information, write licensing proposals, calculate file digests, model revenue splits, and submit private review requests. You remain responsible for the accuracy of your information and for holding the rights or permissions you claim.</p><h2>What is not created automatically</h2><p>A record, file hash, draft, public identity lookup, review request, or calculation does not grant a license, establish legal title, certify compliance, create a payment obligation, execute a transfer, or confirm a blockchain transaction. Final licensing and commercial terms require the relevant agreements and approvals.</p><h2>Permission and responsible use</h2><p>Submit only information you are entitled to use and share. Do not enter private keys, passwords, government identifiers, confidential third-party information without permission, or unlawful material. The workspace is not designed for children to create accounts.</p><h2>Availability and review</h2><p>Provider availability, email delivery, account access, and review timing may vary. A submitted request enters a review queue; acceptance, outcome, and timing are not guaranteed. Export your records for your own continuity.</p>`:`<h2>Original files stay on your device</h2><p>The file fingerprint tool reads your selected file in the browser to calculate SHA-256. This release does not upload the file or store its original bytes. The resulting digest can be included in a record you choose to save.</p><h2>This device versus private cloud</h2><p>Local drafts and local activity are stored in this browser’s localStorage. Other people using the same browser profile may be able to access them. Clearing browser data can remove them. Export a backup before changing devices.</p><p>Signing in does not upload local drafts automatically. Cloud drafts are saved explicitly to the existing CrownThrive ThriveBase service. Access is scoped to your account. Application operators with appropriate administrative authority may access records for operations, security, and review.</p><h2>Account credentials</h2><p>Sign-in details are sent to the authentication provider through the same-origin server adapter. Session tokens are stored in Secure, HttpOnly cookies rather than browser localStorage. Passwords are not included in workspace records or exports.</p><h2>Submitting a review request</h2><p>A review submission records the selected cloud draft version, a snapshot digest, your account identifier, and your review message in the existing CHLOM review workflow. It makes the proposal available to authorized reviewers, not the public exchange.</p><h2>History, retention, and deletion</h2><p>Cloud saves retain version snapshots and review references. Archiving hides a working record but is not erasure. For account or data-deletion requests, contact CrownThrive; applicable legal, security, and agreement-related retention may need separate review. No analytics or advertising scripts are added by this LEX interface; hosting and authentication services may retain operational logs.</p>`}<h2>Questions or corrections</h2><p>Contact <a href="mailto:contact@crownthrive.com">contact@crownthrive.com</a>. These product notices describe the implemented release; a separate signed agreement governs any purchased license or contracted service.</p><p><small>CHLOM LEX · CrownThrive, LLC · Release 1.0 · September 2026</small></p></article>`;}
function render(){page=location.hash.slice(1).split('/')[0]||'home';if(page==='solutions')page='integrations';const views={workspace:overview,assets:()=>recordsPage('asset'),licenses:()=>recordsPage('license'),verify:verifyPage,exchange:exchangePage,splits:splitsPage,activity:activityPage,integrations:ecosystemPage,developers:developersPage,pricing:pricingPage,status:statusPage,privacy:()=>policyPage(false),terms:()=>policyPage(true)};$('#app').innerHTML=page==='home'?home():shell(views[page]?views[page]():heading('This page is not here.','Return to the workspace to continue.',`<a class="button dark" href="#workspace">Open workspace ↗</a>`));document.title=page==='home'?'CHLOM LEX — Your work. Your terms.':(nav.find(n=>n[0]===page)?.[2]||page.charAt(0).toUpperCase()+page.slice(1))+' · CHLOM LEX';$('#account-button').textContent=state.user?'Account':'Sign in';if(page==='exchange')hydrateCatalog();if(page==='status')hydrateStatus();}
async function refreshCloud(){if(!state.user)throw Error('Sign in to access your private cloud records.');const d=await api('drafts');state.cloud=d.drafts||[];const a=await api('activity');state.cloudEvents=a.events||[];}
function authDialog(mode='signin'){state.authMode=mode;if(state.user){openModal(`<h2 id="modal-title">Your connected account</h2><p>${H(state.user.email)}</p><p class="modal-subtitle">Local drafts remain on this device. Cloud drafts belong to your signed-in account.</p><div class="pageactions">${action('Open private cloud','scope-cloud','','dark')}${action('Sign out','logout')}</div>`);return;}openModal(`<div class="authform"><h2 id="modal-title">${mode==='signup'?'Create your workspace.':mode==='recover'?'Recover your account.':'Welcome to your workspace.'}</h2><p>Connect to your private CrownThrive account. You can continue using local tools without signing in.</p>${mode!=='recover'?`<div class="tabs"><button data-action="auth-signin" class="${mode==='signin'?'selected':''}">Sign in</button><button data-action="auth-signup" class="${mode==='signup'?'selected':''}">Create account</button></div>`:''}<form id="auth-form">${field('email','Email address','','email',true,false,'autocomplete="email" maxlength="254"')}${mode==='recover'?'':field('password','Password','','password',true,false,`autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="${mode==='signup'?12:1}" maxlength="128"`)}${mode==='signup'?'<label class="checkfield"><input type="checkbox" required>I have read the use and privacy notices and will only submit information I have permission to share.</label>':''}<div id="auth-result" role="alert"></div><button class="button dark">${mode==='signup'?'Create account':mode==='recover'?'Send recovery instructions':'Sign in'} ↗</button></form><button class="linkbutton" data-action="${mode==='recover'?'auth-signin':'auth-recover'}">${mode==='recover'?'Back to sign in':'Forgot your password?'}</button><small>Local records are never uploaded automatically. <a href="#privacy" data-action="close">Privacy &amp; data</a> · <a href="#terms" data-action="close">Use &amp; boundaries</a></small></div>`);}
function reviewDialog(id){const r=find(id);if(!r)return;openModal(`<h2 id="modal-title">Request a CHLOM review</h2><p class="modal-subtitle">${H(r.title)} · Cloud revision ${H(r.revision)}</p><form id="review-form" data-id="${H(id)}">${area('message','What should the reviewer know?')}<label class="checkfield"><input type="checkbox" required>I authorize this draft version and my message to be shared with authorized CrownThrive reviewers. I understand this is a request, not an approval or rights grant.</label><div id="review-result" role="alert"></div><div class="formfooter"><small>The request enters the existing CHLOM review registry. No original file is sent.</small><button class="button dark">Submit for review ↗</button></div></form>`);$('#review-form textarea').maxLength=4000;}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;try{if(act==='close'){if(b.tagName==='BUTTON')event.preventDefault();closeModal();}else if(act==='auth')authDialog();else if(act.startsWith('auth-'))authDialog(act.slice(5));else if(act==='logout'){b.disabled=true;await api('logout',{});state.user=null;state.cloud=[];state.cloudEvents=[];state.scope='local';closeModal();render();toast('Signed out. Local drafts remain on this device.');}else if(act==='scope-local'){state.scope='local';state.filter='';state.archived=false;render();}else if(act==='scope-cloud'){if(!state.user){authDialog();return;}b.disabled=true;await refreshCloud();state.scope='cloud';state.filter='';closeModal();if(page==='home')location.hash='workspace';else render();}else if(act==='refresh'){b.disabled=true;await refreshCloud();render();toast('Cloud records refreshed.');}else if(act==='new-asset')editDraft('asset');else if(act==='new-license')editDraft('license');else if(act==='category'){editDraft('license');$('#draft-form [name=title]').value=b.dataset.category+' licensing request';}else if(act==='edit'){const r=find(id);if(r)editDraft(r.kind,id);}else if(act==='open')viewDraft(id);else if(act==='license-from')editDraft('license',null,find(id));else if(act==='brief'){const r=find(id);download('chlomlex-license-brief.txt',licenseBrief(r),'text/plain');toast('Draft brief exported. No rights have been granted.');}else if(act==='record-export'){const r=find(id);download('chlomlex-record.json',JSON.stringify({schema:SCHEMA,exported_at:new Date().toISOString(),drafts:[r]},null,2));}else if(act==='export'){download('chlomlex-workspace.json',JSON.stringify({schema:SCHEMA,exported_at:new Date().toISOString(),storage:state.scope,drafts:rows()},null,2));toast('Workspace export created. Keep it somewhere private.');}else if(act==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>2000000)throw Error('Import exceeds 2 MB.');const draftRows=importWorkspace(await f.text());if(state.drafts.length+draftRows.length>1000)throw Error('Import would exceed 1,000 local drafts.');if(!confirm(`Import ${draftRows.length} records as new local drafts? No data will be uploaded.`))return;const now=new Date().toISOString();for(const d of draftRows){const r={...d,id:crypto.randomUUID(),state:'DRAFT',revision:1,created_at:now,updated_at:now};state.drafts.unshift(r);saveEvent('DRAFT_IMPORTED',r);}state.scope='local';persist();render();toast(`${draftRows.length} local drafts imported.`);}catch(e){toast(e.message);}};input.click();}else if(act==='cloud-save'){const r=find(id);if(!state.user){authDialog();return;}if(!confirm('Save this record’s metadata to your private cloud account? Original file bytes will not be uploaded.'))return;b.disabled=true;await api('save',{kind:r.kind,title:r.title,payload:r.payload,revision:0});toast('A private cloud copy was saved. Your local original is unchanged.');await refreshCloud();}else if(act==='review'){if(state.scope!=='cloud')throw Error('Save a cloud copy before requesting review.');reviewDialog(id);}else if(act==='archive'){const r=find(id);if(!confirm('Archive this draft? Cloud history and review records are retained.'))return;if(state.scope==='cloud'){await api('save',{id:r.id,kind:r.kind,title:r.title,payload:r.payload,revision:r.revision,archive:true});await refreshCloud();}else{r.state='ARCHIVED';r.revision++;r.updated_at=new Date().toISOString();saveEvent('ARCHIVED',r);}closeModal();render();toast('Draft archived.');}else if(act==='add-recipient'){event.preventDefault();if(document.querySelectorAll('.splitrow').length>=20)throw Error('Maximum 20 recipients.');$('#split-recipients').insertAdjacentHTML('beforeend',splitRow());}else if(act==='remove-recipient'){event.preventDefault();if(document.querySelectorAll('.splitrow').length>1)b.closest('.splitrow').remove();}else if(act==='catalog-retry')hydrateCatalog();else if(act==='status-retry')hydrateStatus();else if(act==='operator-check'){b.disabled=true;$('#operator-result').innerHTML='<p class="loading">Checking signed-in authority…</p>';try{const d=await api('operator');$('#operator-result').innerHTML=`<pre>${H(JSON.stringify(d,null,2))}</pre>`;}catch(e){$('#operator-result').innerHTML=`<div class="error">${H(e.message)}</div>`;}}}catch(e){toast(e.message);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.filter=event.target.value;$('#record-list').innerHTML=recordList(page==='assets'?'asset':'license');}});
document.addEventListener('change',async event=>{if(event.target.id==='show-archived'){state.archived=event.target.checked;$('#record-list').innerHTML=recordList(page==='assets'?'asset':'license');}if(event.target.id==='draft-file'){const f=event.target.files[0];if(!f)return;const submit=$('#draft-form button[type=submit]');submit.disabled=true;$('#file-note').textContent='Calculating SHA-256 on this device…';try{$('#draft-form [name=digest]').value=await hashFile(f);$('#file-note').textContent=f.name+' · fingerprint calculated; file not uploaded.';}catch(e){$('#file-note').textContent=e.message;}finally{submit.disabled=false;}}if(event.target.id==='asset-select'){const a=rows().find(x=>x.id===event.target.value);if(a)for(const k of ['owner','source','digest','use','exclusions','context']){const field=$(`#draft-form [name=${k}]`);if(field)field.value=a.payload[k]||'';}}});
document.addEventListener('submit',async event=>{const f=event.target;const known=['draft-form','auth-form','review-form','verify-file-form','resolve-form','split-form'];if(!known.includes(f.id))return;event.preventDefault();const button=f.querySelector('button:not([type=button]):last-child')||f.querySelector('button');button.disabled=true;const d=Object.fromEntries(new FormData(f));try{if(f.id==='draft-form'){const id=f.dataset.id,r=id?find(id):null,kind=f.dataset.kind;const title=d.title.trim();delete d.title;d.title=title;if(d.assetId){const a=rows().find(x=>x.id===d.assetId);d.assetTitle=a?.title||'';}const value={kind,title,payload:d};validateDraft(value);if(state.scope==='cloud'){await api('save',{...value,id:id||null,revision:r?.revision||0});await refreshCloud();}else{const now=new Date().toISOString();if(!r&&state.drafts.length>=1000)throw Error('Local draft limit reached. Export existing records for backup.');const row={...value,id:id||crypto.randomUUID(),state:'DRAFT',revision:(r?.revision||0)+1,created_at:r?.created_at||now,updated_at:now};if(r)state.drafts[state.drafts.indexOf(r)]=row;else state.drafts.unshift(row);saveEvent('DRAFT_SAVED',row);}closeModal();render();toast('Draft saved. No license or ownership claim has been approved.');}else if(f.id==='auth-form'){const result=await api(state.authMode,d);if(result.signed_in){const s=await api('session');state.user=s.user;closeModal();render();toast('Signed in. Choose Private cloud to load account records.');}else $('#auth-result').innerHTML=`<div class="success">${H(result.message)}</div>`;}else if(f.id==='review-form'){const r=find(f.dataset.id);const result=await api('review',{id:r.id,revision:r.revision,message:d.message});$('#review-result').innerHTML=`<div class="success">Review request recorded.<br>Case ID: <span class="hash">${H(result.case_id)}</span><br>Status: OPEN. No rights granted or payment executed.</div>`;f.querySelector('button').textContent='Request recorded';f.querySelector('button').disabled=true;await refreshCloud().catch(()=>toast('Review recorded. Refresh cloud records to see the updated state.'));render();return;}else if(f.id==='verify-file-form'){const file=f.querySelector('[type=file]').files[0],digest=await hashFile(file),expected=(d.expected||'').trim().toLowerCase();$('#file-result').innerHTML=`<div class="${expected&&expected!==digest?'error':'success'}"><b>${expected?(digest===expected?'Digests match.':'Digests do not match.'):'Fingerprint calculated.'}</b><p class="hash">${H(digest)}</p><small>${H(file.name)} · ${file.size.toLocaleString()} bytes · Not uploaded.</small></div>`;}else if(f.id==='resolve-form'){const result=await api('resolve',undefined,'&id='+encodeURIComponent(d.identity));const identity=result.identity||result.public_identity||{};$('#identity-result').innerHTML=`<div class="success">Public identity record found.</div><div class="result-grid"><div><small>Display name</small>${H(identity.display_name||'Not provided')}</div><div><small>Registry state</small>${H(identity.state||'Not provided')}</div></div><details><summary>Public record and lineage</summary><pre>${H(JSON.stringify(result,null,2))}</pre></details><div class="notice">This lookup is not a license or an ownership decision.</div>`;}else if(f.id==='split-form'){const names=[...f.querySelectorAll('[name=recipient]')].map(x=>x.value),shares=[...f.querySelectorAll('[name=share]')].map(x=>x.value),result=splitRevenue(d.gross,d.fees,shares),money=c=>new Intl.NumberFormat(undefined,{style:'currency',currency:d.currency}).format(c/100);$('#split-error').innerHTML='';$('#split-result').innerHTML=`<div class="eyebrow">Proposed allocation</div><h2>Every cent accounted for.</h2><div class="moneyrow"><span>Gross amount</span><strong>${money(result.gross_cents)}</strong></div><div class="moneyrow"><span>Fees / deductions</span><strong>${money(result.fee_cents)}</strong></div><div class="moneyrow total"><span>To allocate</span><strong>${money(result.net_cents)}</strong></div>${names.map((n,i)=>`<div class="moneyrow"><span>${H(n)} <small class="muted">${H(shares[i])}%</small></span><strong>${money(result.allocations_cents[i])}</strong></div>`).join('')}<div class="notice">Planning only. No money moved. Taxes and contractual treatment require separate consideration.</div><button class="button small" id="export-split">Export scenario</button>`;$('#export-split').onclick=()=>download('chlomlex-split-scenario.json',JSON.stringify({schema:'ct.chlom.lex-split-preview.v1',currency:d.currency,...result,recipients:names.map((n,i)=>({name:n,percentage:Number(shares[i]),amount_cents:result.allocations_cents[i]})),payment_executed:false},null,2));}}catch(e){const target={'draft-form':'#form-error','auth-form':'#auth-result','review-form':'#review-result','verify-file-form':'#file-result','resolve-form':'#identity-result','split-form':'#split-error'}[f.id];const element=$(target);if(element)element.innerHTML=`<div class="error">${H(e.name==='TimeoutError'?'The service timed out. Your local work is unchanged.':e.message)}</div>`;else toast(e.message);}finally{if(button.isConnected&&button.textContent!=='Request recorded')button.disabled=false;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
